print("Analyzing transformations:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{inp} -> {out}")
    print(f"Length: {len(inp)} -> {len(out)}")

    # Let's see what changes
    min_len = min(len(inp), len(out))
    for j in range(min_len):
        if inp[j] != out[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")

    if len(inp) < len(out):
        print(f"  Extra chars at end: '{out[len(inp):]}'")
    elif len(out) < len(inp):
        print(f"  Missing chars: '{inp[len(out):]}'")

